import{_ as n,C as o,o as e,c as i,a2 as a,b as s,w as l,a as d,E,a3 as g}from"./chunks/framework.BBdhqAg0.js";const C="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",_=JSON.parse('{"title":"조직 체계 관리","description":"","frontmatter":{},"headers":[],"relativePath":"hr-manage/organization.md","filePath":"hr-manage/organization.md","lastUpdated":1793107177000}'),A={name:"hr-manage/organization.md"};function B(h,t,u,f,x,c){const r=o("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="조직-체계-관리" tabindex="-1">조직 체계 관리 <a class="header-anchor" href="#조직-체계-관리" aria-label="Permalink to &quot;조직 체계 관리&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+C+'" alt="조직 체계 관리 및 조직도 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/organization.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>조직 체계 관리</strong>는 회사의 부서 계층 구조, 직급·직위·직책 및 임원 직위 체계를 정의하고, 이를 바탕으로 전사 조직도를 시각화하여 체계적인 인력 배치와 결재선을 지원하는 본사 인사 관리 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[본사 관리] → [인사 조직 관리] → [조직 체계 관리]**를 선택하여 접속합니다. (인사 담당자 및 관리자 권한 필요, 일반 직원은 조직도 열람 지원)</li></ul>',4)),(e(),s(g,null,{default:l(()=>[E(r,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22%F0%9F%8F%A2%20%EB%B6%80%EC%84%9C%20%EC%A0%95%EB%B3%B4%20%EA%B4%80%EB%A6%AC%3Cbr%3E(%EA%B3%84%EC%B8%B5%20%ED%8A%B8%EB%A6%AC%20%26%20%EB%B6%80%EC%84%9C%20%EC%B1%85%EC%9E%84%EC%9E%90%20%EC%A7%80%EC%A0%95)%22%5D%20--%3E%20E%5B%22%F0%9F%8C%B3%20%EC%A0%84%EC%82%AC%20%EC%A1%B0%EC%A7%81%EB%8F%84%20(Org%20Chart)%3Cbr%3E(%EB%B6%80%EC%84%9C%EB%B3%84%20%EC%9D%B8%EC%9B%90%20%EB%B0%8F%20%EC%B1%85%EC%9E%84%EC%9E%90%20%EC%8B%9C%EA%B0%81%ED%99%94)%22%5D%0A%20%20%20%20B%5B%22%F0%9F%93%88%20%EC%A7%81%EA%B8%89%20%EC%B2%B4%EA%B3%84%3Cbr%3E(%EC%97%AD%ED%95%A0%C2%B7%EB%B3%B4%EC%83%81%20%EB%8B%A8%EA%B3%84)%22%5D%20--%3E%20E%0A%20%20%20%20C%5B%22%F0%9F%8E%96%EF%B8%8F%20%EC%A7%81%EC%9C%84%20%EC%B2%B4%EA%B3%84%3Cbr%3E(%EC%A0%84%EB%AC%B8%EC%84%B1%C2%B7%EB%8C%80%EC%99%B8%20%ED%98%B8%EC%B9%AD)%22%5D%20--%3E%20E%0A%20%20%20%20D%5B%22%F0%9F%92%BC%20%EC%A7%81%EC%B1%85%20%EC%B2%B4%EA%B3%84%3Cbr%3E(%ED%8C%80%EC%9E%A5%2C%20%EB%B3%B8%EB%B6%80%EC%9E%A5%2C%20%EB%8C%80%ED%91%9C%EC%9D%B4%EC%82%AC)%22%5D%20--%3E%20E%0A%20%20%20%20D%20--%3E%20F%5B%22%E2%9A%A1%20%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%EC%84%A0%20%EC%9E%90%EB%8F%99%20%EC%82%B0%EC%B6%9C%20%EC%97%B0%EB%8F%99%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h2 id="_1-부서-정보-관리-department" tabindex="-1">1. 부서 정보 관리 (Department) <a class="header-anchor" href="#_1-부서-정보-관리-department" aria-label="Permalink to &quot;1. 부서 정보 관리 (Department)&quot;">​</a></h2><p>부서는 회사의 고유 업무 단위(팀, 본부, 실, 부문 등)를 정의하며, 상위 부서 지정을 통해 무제한 계층 트리(Tree) 구조를 형성합니다.</p><ul><li><strong>계층 레벨 자동 계산</strong>: 상위 부서를 선택하면 해당 부서의 하위 레벨이 자동으로 연산되며, 상위 부서 변경 시 하위 모든 하위 부서의 레벨도 연쇄적으로 갱신됩니다.</li><li><strong>순환 참조 방지</strong>: 자기 자신을 상위 부서로 지정하거나 상·하위 간 꼬임 현상이 발생하지 않도록 시스템 유효성 검사가 작동합니다.</li><li><strong>부서 책임자 지정</strong>: 각 부서의 장(부서장/팀장)을 임직원 목록에서 지정하며, 전자결재 품의 상신 시 부서 내 <strong>1차 결재 승인권자</strong>로 자동 연결됩니다.</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">주요 필드</th><th style="text-align:left;">설명</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>상위 부서</strong></td><td style="text-align:left;">소속된 상위 조직 단위</td><td style="text-align:left;">최상위 부서인 경우 미지정 (Level 1)</td></tr><tr><td style="text-align:left;"><strong>부서명</strong></td><td style="text-align:left;">공식 부서 명칭 (예: 개발사업본부, 경영지원팀)</td><td style="text-align:left;">필수 입력</td></tr><tr><td style="text-align:left;"><strong>주요 업무</strong></td><td style="text-align:left;">부서의 핵심 역할(R&amp;R) 및 직무 설명</td><td style="text-align:left;">부서 소개로 활용</td></tr><tr><td style="text-align:left;"><strong>책임자</strong></td><td style="text-align:left;">부서 책임자 (팀장/부서장)</td><td style="text-align:left;">전자결재 자동 결재선의 기준</td></tr></tbody></table><h2 id="_2-직급-·-직위-·-직책-체계" tabindex="-1">2. 직급 · 직위 · 직책 체계 <a class="header-anchor" href="#_2-직급-·-직위-·-직책-체계" aria-label="Permalink to &quot;2. 직급 · 직위 · 직책 체계&quot;">​</a></h2><p>신입사원과 임직원이 쉽게 구분할 수 있도록 IBS는 <strong>직급</strong>, <strong>직위</strong>, <strong>직책</strong>의 개념을 명확히 분리하여 관리합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">개념 및 정의</th><th style="text-align:left;">실제 사내 예시</th><th style="text-align:left;">주요 활용 영역</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>직급</strong></td><td style="text-align:left;">개인의 역할, 역량, 보상 수준을 나타내는 내부 등급</td><td style="text-align:left;">1등급, 2등급, J1, S2, 사원 1호봉 등</td><td style="text-align:left;">급여 및 승진 심사 기준</td></tr><tr><td style="text-align:left;"><strong>직위</strong></td><td style="text-align:left;">대외적 호칭과 업무 숙련도를 나타내는 명칭</td><td style="text-align:left;">사원, 대리, 과장, 차장, 부장</td><td style="text-align:left;">명함 표기, 대외 커뮤니케이션</td></tr><tr><td style="text-align:left;"><strong>직책</strong></td><td style="text-align:left;">부서 내에서 맡고 있는 지휘·감독 책임</td><td style="text-align:left;">팀원, 팀장, 실장, 본부장, 부문장</td><td style="text-align:left;"><strong>전자결재 결재선 산출</strong>, 전결 권한</td></tr></tbody></table><h3 id="직급-job-grade" tabindex="-1">직급 (Job Grade) <a class="header-anchor" href="#직급-job-grade" aria-label="Permalink to &quot;직급 (Job Grade)&quot;">​</a></h3><ul><li>조직 내에서 개인의 성장 단계와 보상 수준을 일관되게 관리하는 체계입니다.</li><li>최소 근속 연수 및 사내 승급 정책 기준표와 연계되어 정기 승진 심사 대상 선발의 기준이 됩니다.</li></ul><h3 id="직위-position" tabindex="-1">직위 (Position) <a class="header-anchor" href="#직위-position" aria-label="Permalink to &quot;직위 (Position)&quot;">​</a></h3><ul><li>대외적인 호칭과 숙련도 수준을 나타내며, 하나의 직위 내에 복수의 직급 단계가 매핑될 수 있습니다.</li></ul><h3 id="직책-duty-title" tabindex="-1">직책 (Duty Title) <a class="header-anchor" href="#직책-duty-title" aria-label="Permalink to &quot;직책 (Duty Title)&quot;">​</a></h3><ul><li>실질적으로 조직을 지휘하고 관리하는 권한을 의미하며, <strong>전자결재 자동 결재선 산출의 핵심 기준</strong>이 됩니다.</li></ul><h2 id="_3-임원-직위-관리-executive-rank" tabindex="-1">3. 임원 직위 관리 (Executive Rank) <a class="header-anchor" href="#_3-임원-직위-관리-executive-rank" aria-label="Permalink to &quot;3. 임원 직위 관리 (Executive Rank)&quot;">​</a></h2><p>등기 및 비등기 임원에 대한 특화 직위 체계(상무, 전무, 부사장, 사장, 부회장, 회장 등)를 정의하며, 이사회 및 대표이사 전결 규정과 연동됩니다.</p><h2 id="_4-전사-조직도-org-chart" tabindex="-1">4. 전사 조직도 (Org Chart) <a class="header-anchor" href="#_4-전사-조직도-org-chart" aria-label="Permalink to &quot;4. 전사 조직도 (Org Chart)&quot;">​</a></h2><p>등록된 부서 계층과 부서별 배속된 임직원의 현황을 실시간 다이어그램으로 시각화합니다.</p><ul><li><strong>부서별 인원 집계</strong>: 부서 단위별 현재 재직 중인 인원수가 자동으로 카운트됩니다.</li><li><strong>책임자 및 팀원 표출</strong>: 부서장을 최상단에 강조 표시하고 소속 팀원들의 직위와 직책을 직관적으로 조회할 수 있습니다.</li><li><strong>조직도 검색</strong>: 특정 부서명이나 직원명을 검색하여 조직 내 위치와 담당 부서를 즉시 확인할 수 있습니다.</li></ul><h2 id="_5-실무-활용-팁" tabindex="-1">5. 실무 활용 팁 <a class="header-anchor" href="#_5-실무-활용-팁" aria-label="Permalink to &quot;5. 실무 활용 팁&quot;">​</a></h2><ul><li><strong>신입사원 팁 (동료 및 협조 부서 찾기)</strong>: <ul><li>업무 중 다른 부서의 담당자나 팀장을 찾아야 할 때는 <strong>전사 조직도</strong>를 활용하세요. 부서별 조직 구성원과 직책, 내선번호 및 이메일을 바로 확인할 수 있어 원활한 업무 협조에 도움이 됩니다.</li></ul></li><li><strong>인사 담당자 팁 (부서 신설 시 주의사항)</strong>: <ul><li>신규 부서를 생성한 후에는 반드시 **[책임자]**를 지정해 주어야 해당 부서 직원이 휴가나 기안문을 상신할 때 1차 결재선이 정상적으로 자동 산출됩니다.</li></ul></li></ul>',20))])}const m=n(A,[["render",B]]);export{_ as __pageData,m as default};
